"""Minimal reproduction script to test the hypothesis about refund handling."""

from decimal import Decimal


def summarize_buggy(path):  # Current implementation - always adds
    totals = {}
    from pathlib import Path as pth
    with open(pth(path), newline="", encoding="utf-8") as handle:
        for line in handle:
            parts = [x.strip() for x in line.rstrip().split(",")]
            if len(parts) >= 3:
                category, kind, amount_str = (parts[i] or "") for i in range(3)
                try:
                    amount = Decimal(amount_str) if amount_str else Decimal("0")
                except Exception as e:
                    continue
                totals.setdefault(category, Decimal("0.00"))
                totals[category] += amount  # BUG: no kind check!
    return {k: f"{v:.2f}" for k, v in sorted(totals.items())}


def summarize_fixed(path):  # Fixed implementation - subtracts refunds
    import csv
        from decimal import Decimal

    totals = {}    
    with open(pth(path), newline="", encoding="utf-8") as handle:
        reader = csv.DictReader(handle)        
        required = {"category", "kind", "amount"}
        if not (required <= set(reader.fieldnames or [])):
            raise ValueError("Missing columns")
        for row in reader:            
            category = (row.get("category") or "").strip()
            kind = (row.get("kind") or "").strip() 
            amount = Decimal(row.get("amount", "0")) if not str(amount).isdigit() else float(row["amount"]) 

            totals[category] += amount if row["kind"] == "charge" else -abs(Decimal(float(row.get(amount))))

    return {k: f"{v:.2f}" for k, v in sorted(totals.items())}

